; copy.asm -- chapter 13: 256 bytes copied three ways, and a block filled
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "copy.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; 256 bytes copied three ways, each call timed by the debugger; then what
; LDIR and LDI leave in the registers and flags; then a block filled by LDIR.
init:   di
        ld sp, SYS_AREA
        ld hl, $D000            ; the source: byte k is 37 x k
        xor a
mk:     ld (hl), a
        add a, 37
        inc l
        jr nz, mk
c1:     call loopcp             ; one byte at a time, in a loop
c2:     call ldircp             ; with LDIR
c3:     call ldicp              ; with LDI, sixteen at a time
c4:     ld bc, $00FF
        push bc
        pop af                  ; every flag set, to see which LDIR changes
        ld hl, $D000
        ld de, $D400
f1:     ld bc, 4
        ldir
f2:     ld bc, 2
l1:     ldi                     ; BC from 2 to 1
l2:     ldi                     ; and from 1 to 0
l3:     ld hl, $D800
        ld (hl), $AA           ; the first byte ...
        ld de, $D801
fl1:    ld bc, 1023
        ldir                    ; ... copied onto the next, and on
fl2:    nop
stop:   jr stop

; loopcp: 256 bytes from $D000 to $D100, one at a time
loopcp: ld hl, $D000
        ld de, $D100
        ld b, 0                 ; 256 turns
lc1:    ld a, (hl)
        ld (de), a
        inc hl
        inc de
        djnz lc1
        ret

; ldircp: the same bytes to $D200 with LDIR
ldircp: ld hl, $D000
        ld de, $D200
        ld bc, 256
        ldir
        ret

; ldicp: the same bytes to $D300, sixteen LDIs to a turn
ldicp:  ld hl, $D000
        ld de, $D300
        ld bc, 256
li1:    DUP 16                  ; sjasmplus writes the next line 16 times
        ldi
        EDUP
        jp pe, li1              ; P/V: BC is not 0 yet
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
